import json
import os
from threading import Lock

AHCLAUDE_DIR = os.path.expanduser("~/.ahdev")
CACHE_FILE = os.path.join(AHCLAUDE_DIR, "session_cache.json")

_file_lock = Lock()


def _read_cache():
    if not os.path.exists(CACHE_FILE):
        return {}
    try:
        with open(CACHE_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    except (json.JSONDecodeError, IOError):
        return {}


def _write_cache(data):
    os.makedirs(AHCLAUDE_DIR, exist_ok=True)
    with open(CACHE_FILE, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)


def init_session(session_id):
    with _file_lock:
        cache = _read_cache()
        if session_id not in cache:
            cache[session_id] = {
                "session_seq": len(cache) + 1,
                "current_turn": 0,
                "prompts": [],
                "reported_patch_call_ids": []
            }
            _write_cache(cache)


def increment_turn(session_id, prompt):
    with _file_lock:
        cache = _read_cache()
        if session_id not in cache:
            cache[session_id] = {
                "session_seq": len(cache) + 1,
                "current_turn": 0,
                "prompts": [],
                "reported_patch_call_ids": []
            }
        cache[session_id]["current_turn"] += 1
        cache[session_id]["prompts"].append(prompt[:200])
        if len(cache[session_id]["prompts"]) > 50:
            cache[session_id]["prompts"] = cache[session_id]["prompts"][-50:]
        _write_cache(cache)
        return cache[session_id]["current_turn"]


def get_session_info(session_id):
    with _file_lock:
        cache = _read_cache()
        if session_id not in cache:
            return {
                "session_seq": 0,
                "current_turn": 0,
                "prompts": [],
                "reported_patch_call_ids": []
            }
        return cache[session_id]


def set_turn_git_snapshot(session_id, cwd, diff, untracked_files=None):
    if not session_id:
        return
    with _file_lock:
        cache = _read_cache()
        if session_id not in cache:
            cache[session_id] = {
                "session_seq": len(cache) + 1,
                "current_turn": 0,
                "prompts": [],
                "reported_patch_call_ids": []
            }
        cache[session_id]["turn_git_snapshot"] = {
            "cwd": cwd or "",
            "diff": diff or "",
            "untracked_files": untracked_files or [],
        }
        _write_cache(cache)


def mark_patch_reported(session_id, call_id):
    if not session_id or not call_id:
        return False
    with _file_lock:
        cache = _read_cache()
        if session_id not in cache:
            cache[session_id] = {
                "session_seq": len(cache) + 1,
                "current_turn": 0,
                "prompts": [],
                "reported_patch_call_ids": []
            }
        reported = cache[session_id].setdefault("reported_patch_call_ids", [])
        if call_id in reported:
            return False
        reported.append(call_id)
        if len(reported) > 200:
            cache[session_id]["reported_patch_call_ids"] = reported[-200:]
        _write_cache(cache)
        return True
